BEGIN;
SELECT plan(13);
SELECT ok(NOT has_table_privilege('service_role','public.email_mailbox_identity','UPDATE'),'service role cannot rewrite the mailbox binding');
SELECT ok(NOT has_table_privilege('service_role','public.email_mailbox_identity','DELETE'),'service role cannot delete the mailbox binding');
INSERT INTO public.staff(id,first_name,last_name,role,status,email) VALUES('fa250000-0000-4000-8000-000000000099','Development','Admin','ADMINSTAFF','ACTIVE','admin@development.altitutor.com');
SAVEPOINT empty_mailbox;
SET LOCAL ROLE service_role;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
SELECT lives_ok($test$SELECT public.email_assert_mailbox('admin@development.altitutor.com')$test$, 'an empty database binds to the development mailbox');
SELECT is(public.email_assert_mailbox('admin@development.altitutor.com'),'admin@development.altitutor.com','repeated verification retains the same mailbox');
SELECT throws_ok($test$SELECT public.email_assert_mailbox('admin@altitutor.com')$test$, 'P0001', 'Mailbox identity differs from the database binding. Use the matching database; existing mail was preserved.', 'production cannot reuse the development cache');
SELECT public.email_apply_sync_page('inbox',NULL,'dev-page',true,'[{"id":"dev-inbound","threadId":"dev-thread","folderId":"inbox","sender":"tester@example.test","to":["admin@development.altitutor.com"],"receivedAt":"2026-10-01T00:00:00Z","draft":false}]','{}',false,'admin@development.altitutor.com');
SELECT is(public.email_thread_detail('dev-thread')->'messages'->0->>'sender','tester@example.test','development messages remain readable through the thread interface');
SELECT is(jsonb_array_length(public.email_thread_detail('dev-thread')->'links'),0,'the development mailbox is excluded from direct staff participant links');
SELECT public.email_assign_thread('dev-thread','fa250000-0000-4000-8000-000000000099');
SELECT public.email_apply_sync_page('sent',NULL,'dev-sent',true,jsonb_build_array(jsonb_build_object('id','dev-reply','threadId','dev-thread','folderId','sent','sender','admin@development.altitutor.com','to',jsonb_build_array('tester@example.test'),'sentAt',clock_timestamp()+interval '2 seconds','draft',false)),'{}',false,'admin@development.altitutor.com');
SELECT is(public.email_thread_detail('dev-thread')->>'assignedStaffId',NULL,'an Outlook reply from the development mailbox clears responsibility');
SELECT is((SELECT direction FROM public.onboarding_emails WHERE id='dev-reply'),'outbound','development replies project as outbound onboarding correspondence');
SELECT throws_ok($test$SELECT public.email_apply_sync_page('inbox','dev-page','legacy-page',true,'[]','{}')$test$,'P0001','Mailbox identity differs from the database binding. Use the matching database; existing mail was preserved.','legacy production writers cannot modify the development mailbox');
ROLLBACK TO SAVEPOINT empty_mailbox;
SET LOCAL ROLE service_role;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
INSERT INTO public.email_folders(id,name) VALUES('legacy-production-folder','Preserved production folder');
SELECT throws_ok($test$SELECT public.email_assert_mailbox('admin@development.altitutor.com')$test$,'P0001','Mailbox identity differs from the database binding. Use the matching database; existing mail was preserved.','unbound legacy production state cannot be adopted as development');
SELECT is((SELECT name FROM public.email_folders WHERE id='legacy-production-folder'),'Preserved production folder','rejected rebinding preserves existing state');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT throws_ok($test$SELECT public.email_assert_mailbox('admin@altitutor.com')$test$,'42501','permission denied for function email_assert_mailbox','portal users cannot bind or replace mailbox identity');
SELECT * FROM finish();
ROLLBACK;
